  "COMMENT ON COLUMN \"public\".\"hz_fop_source_lines\".\"removed_at\" IS '分录从完整快照移除；来源：完整分录替换；存 UTC；业务日期按 UTC+8 解释；证据：契约／规则待逐项核验';",
  "COMMENT ON COLUMN \"public\".\"hz_fop_source_lines\".\"payload\" IS '必要原始分录；来源：原始 API；；仅保留版本化字段白名单内的必要补充证据，不整包存储API原文、不复制未使用FOP字段、不重复存已规范化列；禁止密钥与Token；证据：契约／规则待逐项核验';",
  "CREATE TABLE \"public\".\"hz_fop_fulfillment_orders\" (\n  \"document_id\" uuid NOT NULL,\n  \"company_id\" uuid NOT NULL,\n  \"dataset_id\" uuid NOT NULL,\n  \"entity_code\" varchar(128) NOT NULL DEFAULT 'hzkj_orders',\n  \"customer_id\" varchar(128),\n  \"paying_customer_id\" varchar(128),\n  \"receiving_customer_id\" varchar(128),\n  \"owner_employee_id\" varchar(128),\n  \"store_id\" varchar(128),\n  \"warehouse_id\" varchar(128),\n  \"raw_order_status\" varchar(64),\n  \"raw_payment_status\" varchar(64),\n  \"customer_paid_at\" timestamptz,\n  \"settlement_currency\" varchar(3),\n  \"raw_purchase_status\" varchar(64),\n  \"shopify_order_number\" varchar(160),\n  \"shopify_order_id\" varchar(128),\n  \"consumer_paid_at\" timestamptz,\n  \"product_amount\" numeric(28,8),\n  \"freight_amount\" numeric(28,8),\n  \"tax_amount\" numeric(28,8),\n  \"discount_amount\" numeric(28,8),\n  \"total_amount\" numeric(28,8),\n  \"raw_stock_usage\" varchar(64),\n  \"raw_delivery_status\" varchar(64),\n  \"outbound_at\" timestamptz,\n  \"raw_refund_status\" varchar(64),\n  \"raw_address_check\" varchar(64),\n  \"recipient_name\" text,\n  \"recipient_phone\" varchar(80),\n  \"recipient_email\" varchar(254),\n  \"country_code\" varchar(2),\n  \"state_name\" text,\n  \"city_name\" text,\n  \"postal_code\" varchar(40),\n  \"address_line1\" text,\n  \"address_line2\" text,\n  CONSTRAINT \"pk_hz_fop_fulfillment_orders_document_id\" PRIMARY KEY (\"document_id\"),\n  CONSTRAINT \"ck_hz_fop_fulfillment_orders_entity_code\" CHECK (\"entity_code\" = 'hzkj_orders')\n);",
  "COMMENT ON TABLE \"public\".\"hz_fop_fulfillment_orders\" IS '履约订单；保存 履约订单 的必要真实业务事实。；仅接收 entity_code=hzkj_orders 的来源登记；同一源单快照、分录及关系在同一事务应用。；customer_paid_at 与 consumer_paid_at 分开；工作台相对时间使用前者，缺失不兜底。；订单产品额、总额、实收额分别保存；全款备货的产品免付事实不再次补回金额。；收件字段精确映射以现有 detail 适配器为准；不同字段不按名称猜测，详见缺口清单。';",
