  "CREATE TABLE \"public\".\"hz_fop_order_flags\" (\n  \"id\" uuid NOT NULL,\n  \"connection_id\" uuid NOT NULL,\n  \"company_id\" uuid NOT NULL,\n  \"dataset_id\" uuid NOT NULL,\n  \"order_document_id\" uuid NOT NULL,\n  \"flag_type\" varchar(40) NOT NULL,\n  \"raw_value\" varchar(100),\n  \"normalized_value\" varchar(40),\n  \"source_document_id\" uuid,\n  \"occurred_at\" timestamptz,\n  \"source_version\" numeric(30,0),\n  CONSTRAINT \"pk_hz_fop_order_flags_id\" PRIMARY KEY (\"id\"),\n  CONSTRAINT \"ck_hz_fop_order_flags_flag_type\" CHECK (\"flag_type\" IN ('interception', 'cancellation')),\n  CONSTRAINT \"ck_hz_fop_order_flags_normalized_value\" CHECK (\n    (\"flag_type\" = 'interception' AND \"normalized_value\" IN ('intercepted', 'released', 'unknown'))\n    OR (\"flag_type\" = 'cancellation' AND \"normalized_value\" IN ('requested', 'cancelled', 'none', 'unknown')))\n);",
  "COMMENT ON TABLE \"public\".\"hz_fop_order_flags\" IS '订单取消／拦截事实；保存明确取消与拦截结果，供待出库排除拦截及红绿标签使用。；所有 RMA 建单应触发拦截是 FOP 流程要求；缺少实际结果时保持 unknown，不能在本地假装已执行。';",
  "COMMENT ON COLUMN \"public\".\"hz_fop_order_flags\".\"id\" IS '本地主键；来源：本地设计；PK；应用生成 UUID；证据：本地设计';",
