  "CREATE TABLE \"public\".\"hz_fop_sync_runs\" (\n  \"id\" uuid NOT NULL,\n  \"connection_id\" uuid NOT NULL,\n  \"company_id\" uuid NOT NULL,\n  \"dataset_id\" uuid NOT NULL,\n  \"trigger_type\" varchar(40) NOT NULL,\n  \"state\" varchar(40) NOT NULL DEFAULT 'pending',\n  \"target_watermarks\" jsonb NOT NULL DEFAULT '{}'::jsonb,\n  \"achieved_watermarks\" jsonb NOT NULL DEFAULT '{}'::jsonb,\n  \"event_count\" bigint NOT NULL DEFAULT 0,\n  \"document_count\" bigint NOT NULL DEFAULT 0,\n  \"started_at\" timestamptz,\n  \"finished_at\" timestamptz,\n  \"last_error_code\" varchar(100),\n  \"created_at\" timestamptz NOT NULL DEFAULT now(),\n  \"updated_at\" timestamptz NOT NULL DEFAULT now(),\n  \"scheduled_for\" timestamptz,\n  CONSTRAINT \"pk_hz_fop_sync_runs_id\" PRIMARY KEY (\"id\"),\n  CONSTRAINT \"ck_hz_fop_sync_runs_trigger_type\" CHECK (\"trigger_type\" IN ('bootstrap', 'scheduled_morning', 'scheduled_business', 'scheduled_off_hours', 'manual', 'notification', 'reconcile', 'post_action')),\n  CONSTRAINT \"ck_hz_fop_sync_runs_state\" CHECK (\"state\" IN ('pending', 'running', 'succeeded', 'partial', 'failed', 'cancelled')),\n  CONSTRAINT \"ck_hz_fop_sync_runs_target_watermarks_shape\" CHECK (jsonb_typeof(\"target_watermarks\") = 'object'),\n  CONSTRAINT \"ck_hz_fop_sync_runs_achieved_watermarks_shape\" CHECK (jsonb_typeof(\"achieved_watermarks\") = 'object')\n);",
  "COMMENT ON TABLE \"public\".\"hz_fop_sync_runs\" IS '同步执行批次；记录多人共用的同步执行，不等同每位用户的刷新结果。；scheduled_for以北京时间计划点转换UTC保存；多实例同一公司/代次/计划点只建一个执行批次。手工请求可合并，保留各自屏障；失败从持久进度继续。';",
