  "CREATE TABLE \"public\".\"hz_fop_sync_issues\" (\n  \"id\" uuid NOT NULL,\n  \"connection_id\" uuid NOT NULL,\n  \"company_id\" uuid NOT NULL,\n  \"dataset_id\" uuid NOT NULL,\n  \"event_id\" uuid,\n  \"document_id\" uuid,\n  \"category\" varchar(64) NOT NULL,\n  \"field_path\" text,\n  \"error_code\" varchar(100) NOT NULL,\n  \"message\" text NOT NULL,\n  \"evidence\" jsonb NOT NULL DEFAULT '{}'::jsonb,\n  \"state\" varchar(40) NOT NULL DEFAULT 'open',\n  \"first_seen_at\" timestamptz NOT NULL DEFAULT now(),\n  \"last_seen_at\" timestamptz NOT NULL DEFAULT now(),\n  \"resolved_at\" timestamptz,\n  CONSTRAINT \"pk_hz_fop_sync_issues_id\" PRIMARY KEY (\"id\"),\n  CONSTRAINT \"ck_hz_fop_sync_issues_category\" CHECK (\"category\" IN ('missing_field', 'missing_relation', 'invalid_version', 'conflict', 'authorization', 'reconciliation', 'source_error')),\n  CONSTRAINT \"ck_hz_fop_sync_issues_evidence_shape\" CHECK (jsonb_typeof(\"evidence\") = 'object'),\n  CONSTRAINT \"ck_hz_fop_sync_issues_state\" CHECK (\"state\" IN ('open', 'retrying', 'resolved', 'accepted_gap'))\n);",
