  "CREATE TABLE \"public\".\"hz_fop_workbench_orders\" (\n  \"document_id\" uuid NOT NULL,\n  \"connection_id\" uuid NOT NULL,\n  \"company_id\" uuid NOT NULL,\n  \"dataset_id\" uuid NOT NULL,\n  \"order_kind\" varchar(40) NOT NULL,\n  \"order_number\" varchar(160) NOT NULL,\n  \"shopify_order_number\" varchar(160),\n  \"customer_id\" varchar(128),\n  \"customer_name\" text,\n  \"current_customer_owner_id\" varchar(128),\n  \"owner_employee_id\" varchar(128),\n  \"warehouse_id\" varchar(128),\n  \"warehouse_name\" text,\n  \"store_name\" text,\n  \"country_code\" varchar(2),\n  \"customer_paid_at\" timestamptz,\n  \"consumer_paid_at\" timestamptz,\n  \"business_created_at\" timestamptz,\n  \"total_amount\" numeric(28,8),\n  \"product_amount\" numeric(28,8),\n  \"freight_amount\" numeric(28,8),\n  \"tax_amount\" numeric(28,8),\n  \"discount_amount\" numeric(28,8),\n  \"currency_code\" varchar(3),\n  \"item_count\" integer,\n  \"total_quantity\" numeric(24,8),\n  \"stage_evidence\" jsonb NOT NULL DEFAULT '{}'::jsonb,\n  \"recipient_snapshot\" jsonb,\n  \"stock_type\" varchar(40),\n  \"stock_lifecycle\" varchar(40),\n  \"intercept_status\" varchar(40),\n  \"cancelled\" boolean,\n  \"projection_revision\" bigint NOT NULL,\n  \"mapping_version\" integer NOT NULL DEFAULT 1,\n  \"rule_version\" integer NOT NULL DEFAULT 1,\n  \"dependency_vector\" jsonb NOT NULL DEFAULT '{}'::jsonb,\n  \"readiness\" varchar(40) NOT NULL DEFAULT 'incomplete',\n  \"published_at\" timestamptz,\n  \"ownership_verified_at\" timestamptz,\n  \"ownership_version\" varchar(160),\n  \"customer_payment_state\" varchar(40) NOT NULL DEFAULT 'unknown',\n  \"order_review_state\" varchar(40) NOT NULL DEFAULT 'unknown',\n  \"purchase_application_state\" varchar(40) NOT NULL DEFAULT 'unknown',\n  \"purchase_coverage_state\" varchar(40) NOT NULL DEFAULT 'unknown',\n  \"platform_order_state\" varchar(40) NOT NULL DEFAULT 'unknown',\n  \"supplier_payment_state\" varchar(40) NOT NULL DEFAULT 'unknown',\n  \"supplier_shipment_state\" varchar(40) NOT NULL DEFAULT 'unknown',\n  \"procurement_stage\" varchar(40) NOT NULL DEFAULT 'unknown',\n  \"stock_readiness_state\" varchar(40) NOT NULL DEFAULT 'unknown',\n  \"allocation_review_state\" varchar(40) NOT NULL DEFAULT 'unknown',\n  \"shopify_sync_state\" varchar(40) NOT NULL DEFAULT 'unknown',\n  \"dispatch_task_state\" varchar(40) NOT NULL DEFAULT 'unknown',\n  \"outbound_state\" varchar(40) NOT NULL DEFAULT 'unknown',\n  \"allocation_created\" boolean,\n  CONSTRAINT \"pk_hz_fop_workbench_orders_document_id\" PRIMARY KEY (\"document_id\"),\n  CONSTRAINT \"ck_hz_fop_workbench_orders_order_kind\" CHECK (\"order_kind\" IN ('fulfillment', 'stock')),\n  CONSTRAINT \"ck_hz_fop_workbench_orders_stage_evidence_shape\" CHECK (jsonb_typeof(\"stage_evidence\") = 'object'),\n  CONSTRAINT \"ck_hz_fop_workbench_orders_dependency_vector_shape\" CHECK (jsonb_typeof(\"dependency_vector\") = 'object'),\n  CONSTRAINT \"ck_hz_fop_workbench_orders_readiness\" CHECK (\"readiness\" IN ('incomplete', 'ready', 'conflict')),\n  CONSTRAINT \"ck_hz_fop_workbench_orders_customer_payment_state\" CHECK (\"customer_payment_state\" IN ('unpaid', 'paid', 'refunded', 'unknown')),\n  CONSTRAINT \"ck_hz_fop_workbench_orders_order_review_state\" CHECK (\"order_review_state\" IN ('pending', 'approved', 'unknown')),\n  CONSTRAINT \"ck_hz_fop_workbench_orders_purchase_application_state\" CHECK (\"purchase_application_state\" IN ('not_created', 'partial', 'created', 'not_required', 'unknown')),\n  CONSTRAINT \"ck_hz_fop_workbench_orders_purchase_coverage_state\" CHECK (\"purchase_coverage_state\" IN ('not_ordered', 'partial', 'ordered', 'cancelled', 'not_required', 'unknown')),\n  CONSTRAINT \"ck_hz_fop_workbench_orders_platform_order_state\" CHECK (\"platform_order_state\" IN ('not_pushed', 'partial', 'pushed', 'not_required', 'unknown')),\n  CONSTRAINT \"ck_hz_fop_workbench_orders_supplier_payment_state\" CHECK (\"supplier_payment_state\" IN ('unpaid', 'partial', 'paid', 'refunded', 'not_required', 'unknown')),\n  CONSTRAINT \"ck_hz_fop_workbench_orders_supplier_shipment_state\" CHECK (\"supplier_shipment_state\" IN ('pending', 'partial', 'shipped', 'not_required', 'unknown')),\n  CONSTRAINT \"ck_hz_fop_workbench_orders_procurement_stage\" CHECK (\"procurement_stage\" IN ('application_pending', 'purchase_order_pending', 'alibaba_pending', 'payment_pending', 'refund_pending', 'supplier_pending', 'supplier_partial', 'shipped', 'cancelled', 'not_required', 'unknown')),\n  CONSTRAINT \"ck_hz_fop_workbench_orders_stock_readiness_state\" CHECK (\"stock_readiness_state\" IN ('incomplete', 'ready', 'unknown')),\n  CONSTRAINT \"ck_hz_fop_workbench_orders_allocation_review_state\" CHECK (\"allocation_review_state\" IN ('pending', 'approved', 'unknown')),\n  CONSTRAINT \"ck_hz_fop_workbench_orders_shopify_sync_state\" CHECK (\"shopify_sync_state\" IN ('pending', 'synced', 'not_required', 'unknown')),\n  CONSTRAINT \"ck_hz_fop_workbench_orders_dispatch_task_state\" CHECK (\"dispatch_task_state\" IN ('dispatch_missing', 'dispatch_draft', 'dispatch_submitted', 'dispatch_approved', 'dispatch_synced', 'unknown')),\n  CONSTRAINT \"ck_hz_fop_workbench_orders_outbound_state\" CHECK (\"outbound_state\" IN ('pending', 'completed', 'unknown'))\n);",
  "COMMENT ON TABLE \"public\".\"hz_fop_workbench_orders\" IS '工作台订单查询投影；五工作台共用同一订单基础，避免复制五套订单；原始事实与派生分类分开。；查询按当前组织／角色、独立资源授权、业务条件过滤后合计排序分页；不永久物化每个用户的获权结果。；当前客户归属与订单归属各自保存；备货库存按客户当前归属，不能一概复用订单历史业务员。；同事务读取 active_dataset_id；事实、展示分录、成员和依赖必须同代次。首次未初始化返回明确未就绪。；readiness 仅表达基础快照结构完整；具体清单资格由 memberships.classification_state 三值判断，不因采购等未接通而伪造已完成或无待办。；五工作台共享本表固定阶段列和同一rule_version；不创建销售／采购／发运／配货／仓库各自的订单或阶段副本。异常、RMA、取消及拦截保持独立事实，不覆盖主流程阶段。；共享投影不保存viewer_account_id、allowed_user_ids或按用户展开的可见结果；当前角色、部门、成员及资源范围在查询时应用。导出授权快照属于有期限的任务，不是永久用户投影。';",
