  "CREATE TABLE \"public\".\"hz_fop_action_requests\" (\n  \"id\" uuid NOT NULL,\n  \"connection_id\" uuid NOT NULL,\n  \"company_id\" uuid NOT NULL,\n  \"dataset_id\" uuid NOT NULL,\n  \"actor_account_id\" uuid NOT NULL,\n  \"operation\" varchar(40) NOT NULL,\n  \"client_request_key\" varchar(160) NOT NULL,\n  \"actor_binding_snapshot\" jsonb NOT NULL DEFAULT '{}'::jsonb,\n  \"authorization_version\" varchar(160) NOT NULL,\n  \"parameters_hash\" varchar(64) NOT NULL,\n  \"state\" varchar(40) NOT NULL DEFAULT 'pending',\n  \"started_at\" timestamptz,\n  \"finished_at\" timestamptz,\n  \"created_at\" timestamptz NOT NULL DEFAULT now(),\n  \"updated_at\" timestamptz NOT NULL DEFAULT now(),\n  CONSTRAINT \"pk_hz_fop_action_requests_id\" PRIMARY KEY (\"id\"),\n  CONSTRAINT \"ck_hz_fop_action_requests_operation\" CHECK (\"operation\" IN ('audit_fulfillment', 'audit_allocation')),\n  CONSTRAINT \"ck_hz_fop_action_requests_actor_binding_snapshot_shape\" CHECK (jsonb_typeof(\"actor_binding_snapshot\") = 'object'),\n  CONSTRAINT \"ck_hz_fop_action_requests_state\" CHECK (\"state\" IN ('pending', 'running', 'succeeded', 'partial', 'blocked', 'failed', 'unknown'))\n);",
