  "CREATE TABLE \"public\".\"hz_fop_action_targets\" (\n  \"id\" uuid NOT NULL,\n  \"connection_id\" uuid NOT NULL,\n  \"company_id\" uuid NOT NULL,\n  \"dataset_id\" uuid NOT NULL,\n  \"request_id\" uuid NOT NULL,\n  \"document_id\" uuid NOT NULL,\n  \"operation\" varchar(40) NOT NULL,\n  \"idempotency_key\" varchar(200) NOT NULL,\n  \"expected_source_version\" varchar(240) NOT NULL,\n  \"parameters_hash\" varchar(64) NOT NULL,\n  \"state\" varchar(40) NOT NULL DEFAULT 'pending',\n  \"outcome_code\" varchar(100),\n  \"outcome_message\" text,\n  \"fop_receipt\" jsonb,\n  \"submitted_at\" timestamptz,\n  \"confirmed_at\" timestamptz,\n  \"attempts\" integer NOT NULL DEFAULT 0,\n  CONSTRAINT \"pk_hz_fop_action_targets_id\" PRIMARY KEY (\"id\"),\n  CONSTRAINT \"ck_hz_fop_action_targets_state\" CHECK (\"state\" IN ('pending', 'running', 'approved', 'already_approved', 'blocked', 'failed', 'unknown'))\n);",
