  "CREATE TABLE \"public\".\"hz_fop_export_jobs\" (\n  \"id\" uuid NOT NULL,\n  \"connection_id\" uuid NOT NULL,\n  \"company_id\" uuid NOT NULL,\n  \"dataset_id\" uuid NOT NULL,\n  \"actor_account_id\" uuid NOT NULL,\n  \"queue_code\" varchar(64) NOT NULL,\n  \"mode\" varchar(40) NOT NULL,\n  \"filters\" jsonb NOT NULL DEFAULT '{}'::jsonb,\n  \"authorization_version\" varchar(160) NOT NULL,\n  \"source_watermarks\" jsonb NOT NULL DEFAULT '{}'::jsonb,\n  \"state\" varchar(40) NOT NULL DEFAULT 'pending',\n  \"row_count\" bigint,\n  \"file_key\" text,\n  \"snapshot_at\" timestamptz,\n  \"expires_at\" timestamptz NOT NULL,\n  \"failure_code\" varchar(100),\n  \"created_at\" timestamptz NOT NULL DEFAULT now(),\n  \"updated_at\" timestamptz NOT NULL DEFAULT now(),\n  \"delivery_authorized_at\" timestamptz,\n  \"delivery_authorization_proof\" jsonb,\n  CONSTRAINT \"pk_hz_fop_export_jobs_id\" PRIMARY KEY (\"id\"),\n  CONSTRAINT \"ck_hz_fop_export_jobs_mode\" CHECK (\"mode\" IN ('filtered', 'selected')),\n  CONSTRAINT \"ck_hz_fop_export_jobs_filters_shape\" CHECK (jsonb_typeof(\"filters\") = 'object'),\n  CONSTRAINT \"ck_hz_fop_export_jobs_source_watermarks_shape\" CHECK (jsonb_typeof(\"source_watermarks\") = 'object'),\n  CONSTRAINT \"ck_hz_fop_export_jobs_state\" CHECK (\"state\" IN ('pending', 'snapshotting', 'generating', 'ready', 'failed', 'expired', 'revoked'))\n);",
